def get_valid_input(prompt, validator=None):
    """
    Prompts the user for input and validates it using a provided validator function.
    If no validator function is provided, it will simply accept any input.
    """
    while True:
        try:
            user_input = input(prompt)
            if validator is not None:
                if not validator(user_input):
                    raise ValueError("Invalid input. Please try again.")
            else:
                return user_input
        except ValueError as e:
            print(e)

